<?php
namespace App\Http\Requests\Erp;
use Illuminate\Foundation\Http\FormRequest;
class IngredientRequest extends FormRequest { public function authorize(): bool { return true; } public function rules(): array { return ['company_id'=>'required|exists:erp_companies,id','supplier_id'=>'nullable|exists:erp_suppliers,id','name'=>'required|string|max:255','category'=>'required|string|max:120','brand'=>'nullable|string|max:120','internal_code'=>'required|string|max:120','barcode'=>'nullable|string|max:120','unit'=>'required|in:g,kg,ml,l,unit','purchase_price'=>'required|numeric|min:0','purchased_quantity'=>'required|numeric|min:0.001','current_quantity'=>'required|numeric|min:0','minimum_quantity'=>'required|numeric|min:0','loss_percentage'=>'required|numeric|min:0|max:100','yield_percentage'=>'required|numeric|min:0.01|max:100','expiration_date'=>'nullable|date','batch'=>'nullable|string|max:120','stock_location'=>'nullable|string|max:120','observations'=>'nullable|string','status'=>'required|in:active,inactive']; } }
